    Bug 1978987 follow-up - Clean up a left-over account causing a subsequent test to fail. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D271546

diff --git a/mail/test/browser/account/browser_mailAccountSetupWizard.js b/mail/test/browser/account/browser_mailAccountSetupWizard.js
index e2f2e4e2aa0..339c45d581a 100644
--- a/mail/test/browser/account/browser_mailAccountSetupWizard.js
+++ b/mail/test/browser/account/browser_mailAccountSetupWizard.js
@@ -844,4 +844,9 @@ registerCleanupFunction(function () {
   DNS.srv = _srv;
   DNS.txt = _txt;
   Services.prefs.clearUserPref("mail.suppressAlertsForTests");
+  for (const account of MailServices.accounts.accounts) {
+    if (!["account1", "account2"].includes(account.key)) {
+      MailServices.accounts.removeAccount(account, false);
+    }
+  }
 });
diff --git a/mail/test/browser/account/head.js b/mail/test/browser/account/head.js
index dc3027d4adc..59510d1d02c 100644
--- a/mail/test/browser/account/head.js
+++ b/mail/test/browser/account/head.js
@@ -515,3 +515,34 @@ function removeAccountInternal(tab, account) {
   MailServices.outgoingServer.deleteServer(outgoing);
   win.replaceWithDefaultSmtpServer(smtpKey);
 }
+
+// Report and remove any accounts/servers that aren't in the test manifest.
+// If we register a cleanup function here, it will run before any other
+// cleanup function has had a chance to run. Instead, when it runs register
+// another cleanup function which will run last.
+registerCleanupFunction(function () {
+  registerCleanupFunction(async function () {
+    for (const server of MailServices.accounts.allServers) {
+      if (!["server1", "server2"].includes(server.key)) {
+        Assert.report(
+          true,
+          undefined,
+          undefined,
+          `Found server ${server.key} at the end of the test run`
+        );
+        MailServices.accounts.removeIncomingServer(server, false);
+      }
+    }
+    for (const account of MailServices.accounts.accounts) {
+      if (!["account1", "account2"].includes(account.key)) {
+        Assert.report(
+          true,
+          undefined,
+          undefined,
+          `Found account ${account.key} at the end of the test run`
+        );
+        MailServices.accounts.removeAccount(account, false);
+      }
+    }
+  });
+});
